-- 0320_strike_economy: Krunker Strike's economy and progression, its own tables (keyed by account,
-- never Box Office's players / inventory / kr_transactions). Owner: strike-economy.
-- GENERATED by tools/strike/gen_economy.py from tools/strike/strike_data.json (FRVR Krunker Strike 1.37.2)
-- and assets/skins.json: do not edit; regenerate. Additive: new tables only.
--
-- Catalogue (seeded below; kn_brain serves it, services/brain/strike_econ.c): strike_item_defs (FRVR's
-- item definitions), strike_pools / strike_pool_items (wheel pools), strike_wheels / strike_wheel_slices
-- (spin wheels: odds = the bundle's crate tiers), strike_products (the store; no real money),
-- strike_missions_def (daily missions), strike_track (account progression rewards), strike_config.
-- Per account: strike_wallets (xp, kr = krunkies, spin tickets, ...), strike_items (inventory),
-- strike_loadout (equipped per slot), strike_progress (XP, stats, golden spin meter: leaderboards),
-- strike_wheel_spins, strike_daily_missions, strike_track_claims, strike_purchases, strike_ledger,
-- strike_match_results (commit idempotency).

CREATE TABLE strike_item_defs (
    id          VARCHAR(64) PRIMARY KEY,
    item_type   SMALLINT NOT NULL,
    weapon      SMALLINT NOT NULL DEFAULT -1,
    name        VARCHAR(255) NOT NULL DEFAULT '',
    rarity      SMALLINT NOT NULL DEFAULT -1,
    skin_index  INT NOT NULL DEFAULT -1,
    class_id    SMALLINT NOT NULL DEFAULT -1,
    is_default  SMALLINT NOT NULL DEFAULT 0,
    spinnable   SMALLINT NOT NULL DEFAULT 0,
    origin      VARCHAR(255) NOT NULL DEFAULT '',
    sort        INT NOT NULL DEFAULT 0
);
CREATE TABLE strike_pools (
    id      VARCHAR(64) PRIMARY KEY,
    name    VARCHAR(255) NOT NULL DEFAULT '',
    color   VARCHAR(255) NOT NULL DEFAULT '',
    rarity  SMALLINT NOT NULL DEFAULT 0,
    sort    INT NOT NULL DEFAULT 0
);
CREATE TABLE strike_pool_items (
    pool_id VARCHAR(64) NOT NULL,
    item_id VARCHAR(64) NOT NULL,
    PRIMARY KEY (pool_id, item_id)
);
CREATE TABLE strike_wheels (
    id              VARCHAR(64) PRIMARY KEY,
    name            VARCHAR(255) NOT NULL DEFAULT '',
    name_key        VARCHAR(255) NOT NULL DEFAULT '',
    wheel_type      VARCHAR(255) NOT NULL DEFAULT '',
    price_currency  VARCHAR(255) NOT NULL DEFAULT '',
    price_amount    INT NOT NULL DEFAULT 0,
    time_between_s  INT NOT NULL DEFAULT 0,
    max_accumulated INT NOT NULL DEFAULT 0,
    heroic_chance   DOUBLE NOT NULL DEFAULT 0,
    hide_in_shop    SMALLINT NOT NULL DEFAULT 0,
    counts_golden   SMALLINT NOT NULL DEFAULT 0,
    button_color    VARCHAR(255) NOT NULL DEFAULT '',
    category        VARCHAR(255) NOT NULL DEFAULT '',
    active          SMALLINT NOT NULL DEFAULT 1,
    sort            INT NOT NULL DEFAULT 0
);
CREATE TABLE strike_wheel_slices (
    wheel_id      VARCHAR(64) NOT NULL,
    pool_id       VARCHAR(64) NOT NULL,
    weight        DOUBLE NOT NULL,
    guaranteed_if INT NOT NULL DEFAULT 0,
    sort          INT NOT NULL DEFAULT 0,
    PRIMARY KEY (wheel_id, pool_id)
);
CREATE TABLE strike_products (
    id             VARCHAR(64) PRIMARY KEY,
    section        VARCHAR(255) NOT NULL DEFAULT '',
    title          VARCHAR(255) NOT NULL DEFAULT '',
    price_type     VARCHAR(255) NOT NULL DEFAULT '',
    price_currency VARCHAR(255) NOT NULL DEFAULT '',
    price_amount   INT NOT NULL DEFAULT 0,
    rewards        TEXT NOT NULL,
    refresh_s      INT NOT NULL DEFAULT 0,
    max_purchases  INT NOT NULL DEFAULT 0,
    active         SMALLINT NOT NULL DEFAULT 1,
    sort           INT NOT NULL DEFAULT 0
);
CREATE TABLE strike_missions_def (
    id           VARCHAR(64) PRIMARY KEY,
    mission_type VARCHAR(255) NOT NULL DEFAULT '',
    mkey         VARCHAR(255) NOT NULL DEFAULT '',
    text_key     VARCHAR(255) NOT NULL DEFAULT '',
    required     INT NOT NULL,
    max_mode     SMALLINT NOT NULL DEFAULT 0,
    weight       INT NOT NULL DEFAULT 1,
    rewards      TEXT NOT NULL,
    active       SMALLINT NOT NULL DEFAULT 1,
    sort         INT NOT NULL DEFAULT 0
);
CREATE TABLE strike_track (
    slot_id       VARCHAR(64) PRIMARY KEY,
    level         INT NOT NULL,
    player_choice SMALLINT NOT NULL DEFAULT 0,
    rewards       TEXT NOT NULL
);
CREATE TABLE strike_config (
    ckey   VARCHAR(64) PRIMARY KEY,
    value  TEXT NOT NULL
);

CREATE TABLE strike_wallets (
    account_id BIGINT NOT NULL,
    currency   VARCHAR(160) NOT NULL,
    amount     BIGINT NOT NULL DEFAULT 0 CHECK (amount >= 0),
    PRIMARY KEY (account_id, currency)
);
CREATE TABLE strike_items (
    account_id BIGINT NOT NULL,
    item_id    VARCHAR(160) NOT NULL,
    count      INT NOT NULL DEFAULT 1 CHECK (count >= 0),
    first_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (account_id, item_id)
);
CREATE TABLE strike_loadout (
    account_id BIGINT NOT NULL,
    slot       VARCHAR(160) NOT NULL,
    item_id    VARCHAR(160) NOT NULL,
    PRIMARY KEY (account_id, slot)
);
CREATE TABLE strike_progress (
    account_id        BIGINT NOT NULL PRIMARY KEY,
    xp                BIGINT NOT NULL DEFAULT 0,
    kills             BIGINT NOT NULL DEFAULT 0,
    deaths            BIGINT NOT NULL DEFAULT 0,
    wins              BIGINT NOT NULL DEFAULT 0,
    games             BIGINT NOT NULL DEFAULT 0,
    score             BIGINT NOT NULL DEFAULT 0,
    time_ms           BIGINT NOT NULL DEFAULT 0,
    golden_spin_count INT NOT NULL DEFAULT 0,
    updated_at        DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
);
CREATE INDEX strike_progress_xp_idx ON strike_progress (xp);
CREATE INDEX strike_progress_kills_idx ON strike_progress (kills);
CREATE INDEX strike_progress_wins_idx ON strike_progress (wins);
CREATE INDEX strike_progress_score_idx ON strike_progress (score);
CREATE TABLE strike_wheel_spins (
    account_id   BIGINT NOT NULL,
    wheel_id     VARCHAR(160) NOT NULL,
    spins        BIGINT NOT NULL DEFAULT 0,
    last_spin_ms BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY (account_id, wheel_id)
);
CREATE TABLE strike_daily_missions (
    account_id BIGINT NOT NULL,
    day        INT NOT NULL,
    mission_id VARCHAR(160) NOT NULL,
    progress   BIGINT NOT NULL DEFAULT 0,
    completed  SMALLINT NOT NULL DEFAULT 0,
    claimed    SMALLINT NOT NULL DEFAULT 0,
    PRIMARY KEY (account_id, day, mission_id)
);
CREATE TABLE strike_track_claims (
    account_id BIGINT NOT NULL,
    slot_id    VARCHAR(160) NOT NULL,
    choice     INT NOT NULL DEFAULT 0,
    claimed_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (account_id, slot_id)
);
CREATE TABLE strike_purchases (
    account_id BIGINT NOT NULL,
    product_id VARCHAR(160) NOT NULL,
    period     BIGINT NOT NULL DEFAULT 0,
    count      INT NOT NULL DEFAULT 0,
    PRIMARY KEY (account_id, product_id, period)
);
CREATE TABLE strike_ledger (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    account_id BIGINT NOT NULL,
    kind       VARCHAR(160) NOT NULL,
    currency   VARCHAR(160) NOT NULL DEFAULT '',
    delta      BIGINT NOT NULL DEFAULT 0,
    item_id    VARCHAR(160) NOT NULL DEFAULT '',
    ref        VARCHAR(160) NOT NULL DEFAULT '',
    at         DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
);
CREATE INDEX strike_ledger_account_idx ON strike_ledger (account_id, id);
CREATE TABLE strike_match_results (
    match_key  VARCHAR(160) NOT NULL,
    account_id BIGINT NOT NULL,
    at         DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (match_key, account_id)
);

-- ---- the catalogue (seed rows)
